// Define how Sequelize represents one row from the existing exercises table.
// DataTypes describes each column, and the shared Sequelize instance connects
// this model to the configured database.
import { DataTypes } from "sequelize";
import sequelize from "../config/db.js";

// This model describes the existing database table; it does not create or
// alter it. Attribute names match the existing snake_case column names.
const Exercise = sequelize.define(
  "Exercise",
  {
    // Primary key generated by the database when a row is inserted.
    id: {
      type: DataTypes.INTEGER,
      primaryKey: true,
      autoIncrement: true,
      allowNull: false,
    },
    external_id: {
      type: DataTypes.STRING(100),
      allowNull: true,
      // When present, this value must be unique across exercise rows.
      unique: true,
    },
    // Required display name; the remaining fields provide optional details.
    name: {
      type: DataTypes.STRING(150),
      allowNull: false,
    },
    body_part: {
      type: DataTypes.STRING(100),
      allowNull: true,
    },
    target_muscle: {
      type: DataTypes.STRING(100),
      allowNull: true,
    },
    equipment: {
      type: DataTypes.STRING(100),
      allowNull: true,
    },
    instructions: {
      type: DataTypes.TEXT,
      allowNull: true,
    },
    gif_url: {
      type: DataTypes.STRING(500),
      allowNull: true,
    },
  },
  {
    // Explicit mapping avoids Sequelize guessing a table name.
    tableName: "exercises",
    // Sequelize manages timestamps using the table's existing column names.
    timestamps: true,
    createdAt: "created_at",
    updatedAt: "updated_at",
    // These indexes help the database filter exercises by common categories.
    indexes: [
      { fields: ["body_part"] },
      { fields: ["target_muscle"] },
      { fields: ["equipment"] },
    ],
  }
);

export default Exercise;
